/** Deal-breakers fail a country whatever its total score. */
export const DEAL_BREAKERS = [
  { id: "fx", title: "Currency Convertibility", label: "Currency cannot be converted or profits taken out of the country" },
  { id: "retroactive", title: "Retroactive Changes", label: "Contracts changed after the fact, with no fix" },
  { id: "ownership", title: "Foreign Ownership", label: "Foreign owners cannot hold a controlling stake" },
] as const;

export type DealBreakerId = (typeof DEAL_BREAKERS)[number]["id"];

export interface PolicyIndicator {
  id: string;
  name: string;
  value: number;
  year: number;
  /** This indicator's 1-5 score (percentile across countries). */
  score: number;
  source: string;
  /** Text shown instead of the number, for yes/no style indicators. */
  display?: string;
  /** One plain-language sentence explaining what the indicator says about this country. */
  reason?: string;
}

export interface CountryPolicyItem {
  title: string;
  year?: string;
  instrument: string;
  url?: string;
}

export interface CountryPolicy {
  /** ISO 3166-1 alpha-2. */
  country: string;
  isSample: boolean;
  /** "indicators": computed from published indicators. "researched": assessed by hand with sources. */
  basis?: "indicators" | "researched";
  /** The indicators behind each pillar score (indicator-based scores only). */
  indicators?: Partial<Record<PillarId, PolicyIndicator[]>>;
  /** Recent renewable policies in force (Climate Policy Database). */
  policies?: CountryPolicyItem[];
  scores: Record<PillarId, number>;
  dealBreakers: DealBreakerId[];
  assessedAt: string;
  sources: { publisher: string; title: string; url: string; retrievedAt: string }[];
}

// Researched PROFITS scores go here, one entry per country, each with its sources.
// A researched entry replaces the indicator-based baseline for that country.
export const researchedPolicies: CountryPolicy[] = [];

import { indicatorPolicies } from "./policy-scores";

const researched = new Set(researchedPolicies.map((p) => p.country));
export const countryPolicies: CountryPolicy[] = [
  ...researchedPolicies,
  ...indicatorPolicies.filter((p) => !researched.has(p.country)),
];
